def transform(grid):
    n=len(grid); colors=[]
    for row in grid:
        vals=set(row)-{0}
        if vals: colors.append(next(iter(vals)))
    # Fill blank rows using the repeating sequence of stripe colors.
    out=[]
    for i,row in enumerate(grid):
        vals=set(row)-{0}
        if vals: c=next(iter(vals))
        else: c=colors[i%len(colors)]
        out.append([c]*len(row))
    return out
